package com.campusmart.controller;
import com.campusmart.entity.*;import com.campusmart.repository.*;import com.campusmart.service.OrderService;import com.campusmart.dto.OrderDtos;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController{private final UserRepository users;private final ProductRepository products;private final OrderRepository orders;private final OrderService orderService;public AdminController(UserRepository u,ProductRepository p,OrderRepository o,OrderService os){users=u;products=p;orders=o;orderService=os;}@GetMapping("/stats")public Map<String,Object>stats(){return Map.of("users",users.count(),"students",users.countByRole(User.Role.STUDENT),"products",products.count(),"activeListings",products.countByAvailableTrue(),"orders",orders.count(),"pendingOrders",orders.countByStatus(Order.Status.PENDING),"completedOrders",orders.countByStatus(Order.Status.DELIVERED));}@GetMapping("/users")public List<User>allUsers(){return users.findAll();}@GetMapping("/products")public List<Product>allProducts(){return products.findAll();}@PutMapping("/orders/{id}/status")public void status(@PathVariable Long id,@Valid @RequestBody OrderDtos.StatusUpdate d){orderService.status(id,d.status());}}
